/**
 * Readable names for the types generated from the backend's OpenAPI spec.
 *
 * `schema.d.ts` is generated by `npm run api:types` and must not be edited.
 * When the backend changes a DTO, regenerating it makes the TypeScript compiler
 * point at every place in the frontend that no longer fits.
 */
import type { components, paths } from './schema'

type Schemas = components['schemas']

// Enums
export type Role = Schemas['Role']
export type MusicItemType = Schemas['MusicItemType']
export type Reaction = Schemas['Reaction']

// Responses
export type User = Schemas['UserDto']
export type MusicItem = Schemas['MusicItemDto']
export type CollectionEntry = Schemas['CollectionEntryDto']
export type Comment = Schemas['CommentDto']
export type Rating = Schemas['RatingDto']
export type RatingSummary = Schemas['RatingSummaryDto']
export type PageMeta = Schemas['PageMetaDto']
export type ApiErrorBody = Schemas['ApiErrorDto']

/** A page of a list endpoint: `{ data: T[], meta: { page, limit, total } }`. */
export interface Page<T> {
  data: T[]
  meta: PageMeta
}

// Request bodies
export type CreateMusicItem = Schemas['CreateMusicItemDto']
export type UpdateMusicItem = Schemas['UpdateMusicItemDto']
export type AddCollectionEntry = Schemas['AddCollectionEntryDto']
export type UpdateCollectionEntry = Schemas['UpdateCollectionEntryDto']
export type CreateComment = Schemas['CreateCommentDto']
export type Rate = Schemas['RateDto']

// Query parameters, taken from the path definitions
export type MusicItemQuery = NonNullable<paths['/api/v1/music-items']['get']['parameters']['query']>
export type CollectionQuery = NonNullable<
  paths['/api/v1/users/{userId}/collection']['get']['parameters']['query']
>
export type AllCollectionsQuery = NonNullable<
  paths['/api/v1/collections']['get']['parameters']['query']
>
